(()=>{
 const currencyFor={en:'USD',zh:'CNY',de:'EUR',fr:'EUR',es:'EUR',it:'EUR',pt:'EUR',nl:'EUR',pl:'PLN',sv:'SEK',da:'DKK',no:'NOK',fi:'EUR',cs:'CZK',hu:'HUF',ro:'RON',el:'EUR',tr:'TRY',uk:'UAH',ru:'RUB',ja:'JPY',ko:'KRW',ar:'SAR',id:'IDR'};
 const pickers=[...document.querySelectorAll('.compact-picker')];
 const close=except=>pickers.forEach(p=>{if(p===except)return;p.querySelector('.picker-panel').hidden=true;p.querySelector('.picker-toggle').setAttribute('aria-expanded','false');});
 function sync(p){const select=p.querySelector('select');p.querySelector('.picker-value').textContent=select.selectedOptions[0]?.textContent||'';p.querySelectorAll('[data-value]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===select.value)));}
 for(const p of pickers){const select=p.querySelector('select'),toggle=p.querySelector('.picker-toggle'),panel=p.querySelector('.picker-panel');
  for(const option of select.options){const button=document.createElement('button');button.type='button';button.textContent=option.textContent;button.dataset.value=option.value;button.lang=p.dataset.picker==='language'?option.value:'en';button.dir='ltr';button.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync(p);close();toggle.focus();});panel.append(button);}
  toggle.addEventListener('click',()=>{const open=panel.hidden;close(p);panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open)panel.querySelector('[aria-pressed=true]')?.focus();});
  select.addEventListener('change',()=>{sync(p);if(select.id==='language'){const currency=document.querySelector('#currency');currency.value=currencyFor[select.value]||'USD';currency.dispatchEvent(new Event('change',{bubbles:true}));pickers.filter(x=>x.dataset.picker==='currency').forEach(sync);}});sync(p);
 }
 document.addEventListener('click',e=>{if(!e.target.closest('.compact-picker'))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});window.addEventListener('litbuy:languagechange',()=>pickers.forEach(sync));
 // Keep suggestions short and usable on both search forms, with real catalog links.
 document.querySelectorAll('form.mast-search,form.catalog-search').forEach(form=>{const input=form.querySelector('[name=q]');if(!input)return;input.placeholder='Search shoes, hoodies, T-shirts or seller item ID…';input.setAttribute('list','product-search-hints');if(!document.querySelector('#product-search-hints')){const list=document.createElement('datalist');list.id='product-search-hints';['Shoes','Hoodie','T-Shirt','Jacket','Pants','Socks','Bag','Jersey'].forEach(word=>{const o=document.createElement('option');o.value=word;list.append(o);});document.body.append(list);}const hints=document.createElement('div');hints.className='search-hints';hints.setAttribute('aria-label','Popular searches');['Shoes','Hoodie','T-Shirt','Jacket'].forEach(word=>{const a=document.createElement('a');a.textContent=word;a.href='/products/?q='+encodeURIComponent(word);hints.append(a);});form.insertAdjacentElement('afterend',hints);});
})();
